// course 1: solid 8x8 dark grey
fill(-4,-4,8,8,72,{kit:"bricks"});
// course 2: 8x8 again, slightly rough using mixed greys
fill(-4,-4,8,8,0,{kit:"bricks"});
// course 3: 6x6 step-in in dark grey
fill(-3,-3,6,6,72,{kit:"bricks"});
log("base parts: "+count());

const cols=[4,4,15,15];
for(let c=0;c<4;c++){ ring(-3,-3,6,6,1,cols[c],{bond:c%2}); }
// ledge floor so the narrower tower has support
fill(-3,-3,6,6,15,{kit:"plates"});
log("parts: "+count());

// balcony: 6x6 plate ring overhanging the tower top
fill(-3,-3,6,6,72,{kit:"plates"});
// railing posts at corners + mid edges
const posts=[[-3,-3],[2,-3],[-3,2],[2,2],[-1,-3],[0,-3],[-1,2],[0,2],[-3,-1],[-3,0],[2,-1],[2,0]];
for(const p of posts) put('3062b',0,p[0],p[1]);
// glazed lantern room: 4x4 ring, 2 courses trans-clear
ring(-2,-2,4,4,1,47,{bond:0});
ring(-2,-2,4,4,1,47,{bond:1});
log("parts: "+count());

// raise the three short outcrops to deck level and tie them into the base
put('3005',72,4,-1); put('3005',0,4,2); put('3005',72,2,4);
put('3023',72,3,-1); put('3023',72,3,2); put('3023',72,2,3,90);
log("parts: "+count());
